import z3
import itertools
import time

n = 25
min_deg = 3
max_deg = 7

# Create edge variables
edge_vars = {}
for i in range(n):
    for j in range(i+1, n):
        edge_vars[(i,j)] = z3.Bool(f"e_{i}_{j}")

# Helper to get variable
def e(i, j):
    return edge_vars[(min(i,j), max(i,j))]

# Degree constraints
constraints = []
for i in range(n):
    incident = [e(i, j) for j in range(n) if j != i]
    constraints.append(z3.Sum([z3.If(v, 1, 0) for v in incident]) >= min_deg)
    constraints.append(z3.Sum([z3.If(v, 1, 0) for v in incident]) <= max_deg)

# We'll add cycle constraints lazily
solver = z3.Solver()
solver.add(constraints)

def find_short_cycle(edges_set, max_len=6):
    """Find a cycle of length <= max_len in the graph represented by edges_set"""
    # Build adjacency list
    adj = {i: set() for i in range(n)}
    for (u, v) in edges_set:
        adj[u].add(v)
        adj[v].add(u)

    # Use BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS to find cycle
        parent = {start: -1}
        depth = {start: 0}
        queue = [start]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if v not in depth:
                    depth[v] = depth[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent.get(u, -1):
                    # Found a cycle
                    # Reconstruct
                    cycle_len = depth[u] + depth[v] + 1
                    if cycle_len <= max_len:
                        # Reconstruct cycle
                        cycle = [u]
                        cur = u
                        while cur != start:
                            cur = parent[cur]
                            if cur == -1:
                                break
                            cycle.append(cur)
                        cycle2 = [v]
                        cur = v
                        while cur != start:
                            cur = parent[cur]
                            if cur == -1:
                                break
                            cycle2.append(cur)
                        if cycle_len <= max_len:
                            # Find the actual cycle
                            # We need to find the cycle based on the parents
                            # The cycle is: path from start to u + edge (u,v) + path from v to start
                            # Let's reconstruct properly
                            path_u = [u]
                            cur = u
                            while cur != start:
                                cur = parent[cur]
                                path_u.append(cur)
                            path_v = [v]
                            cur = v
                            while cur != start:
                                cur = parent[cur]
                                path_v.append(cur)
                            # Remove common suffix
                            while len(path_u) >= 2 and len(path_v) >= 2 and path_u[-1] == path_v[-1] and path_u[-2] == path_v[-2]:
                                path_u.pop()
                                path_v.pop()
                            cycle_verts = path_u + list(reversed(path_v))
                            return cycle_verts
        # Also check for odd cycles where we revisit same level
    return None

def find_all_short_cycles(edges_set, max_len=6):
    """Find all cycles up to length max_len"""
    adj = {i: set() for i in range(n)}
    for (u, v) in edges_set:
        adj[u].add(v)
        adj[v].add(u)

    cycles = []
    # Simple enumeration for small lengths
    # length 3
    for i in range(n):
        for j in adj[i]:
            if j > i:
                for k in adj[i] & adj[j]:
                    if k > j:
                        cycles.append([i, j, k])
    # length 4
    for i in range(n):
        for j in adj[i]:
            if j > i:
                for k in adj[j]:
                    if k != i:
                        for l in adj[k]:
                            if l != j and l in adj[i]:
                                if sorted([i,j,k,l]) == [i,j,k,l] and len({i,j,k,l}) == 4:
                                    cycles.append([i,j,k,l])
    # length 5 (brute force but limited)
    for a in range(n):
        for b in adj[a]:
            if b > a:
                for c in adj[b]:
                    if c not in (a,b):
                        for d in adj[c]:
                            if d not in (a,b,c):
                                for e in adj[d]:
                                    if e not in (a,b,c,d) and e in adj[a]:
                                        if all(x < y for x, y in zip(sorted([a,b,c,d,e]), sorted([a,b,c,d,e])[1:])) and a == min([a,b,c,d,e]):
                                            cycles.append([a,b,c,d,e])
    # length 6
    # We'll skip for now, but we can add
    return cycles

def find_short_cycle_sat(model, max_len=6):
    """Given a Z3 model, extract edges and find short cycles"""
    edges = []
    for (i,j), var in edge_vars.items():
        if z3.is_true(model[var]):
            edges.append((i,j))
    return find_all_short_cycles(set(edges), max_len)

