from collections import deque

def bfs_shortest_cycle(start, adj):
    """Return length of shortest cycle involving start, or inf"""
    parent = {start: -1}
    depth = {start: 0}
    q = deque([start])
    shortest = float('inf')

    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in depth:
                depth[v] = depth[u] + 1
                parent[v] = u
                q.append(v)
            elif v != parent.get(u, -1):
                # Found a cycle
                cycle_len = depth[u] + depth[v] + 1
                if cycle_len < shortest:
                    shortest = cycle_len
    return shortest

# Overall girth
